"""Explain RCU-sync exit, replay, idle and lifetime cleanup."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1437': ('공사팀 두 명 중 한 명이 나갔다고 지름길을 열 수는 없습니다. 마지막 사람이 나가도 안전 확인을 마친 뒤에 열어야 합니다.', '마지막 updater의 exit만 종료 전환을 시작하는 이유를 배웁니다.', 'PASSED·2 → A exit: PASSED·1 → B exit: EXIT·0과 콜백 예약을 적으세요. 두 번의 exit 중 어느 것이 마지막인지 표시하세요.', ['updater는 읽기 경로 전환에 참여한 작업입니다. enter 한 번으로 gp_count를 하나 늘렸다면 대응하는 exit 한 번으로 하나 줄여야 합니다. gp_count는 아직 exit하지 않은 참여자 수입니다.', 'rcu_sync_exit는 먼저 IDLE에서 잘못 호출됐는지 경고를 검사합니다. 내부 잠금을 잡은 뒤에는 이미 count가 0인지도 검사합니다. 경고는 실수를 알리는 장치이지, 잘못된 호출을 취소하거나 수를 자동으로 복구하는 장치가 아닙니다.', '!--rsp->gp_count에서 --는 먼저 1을 빼라는 뜻입니다. 앞의 !는 뺀 결과가 0이면 참이 됩니다. 그래서 원래 2였다면 1이 되어 안쪽으로 가지 않고, 원래 1이었다면 0이 되어 마지막 종료 처리를 합니다.', '한 명이 남았다면 그 참여자가 아직 전환을 이용합니다. 따라서 count=2에서 한 번 exit했다고 상태를 IDLE로 바꾸지 않습니다. PASSED였다면 그대로 PASSED이며 빠른 읽기 길은 닫혀 있습니다.', '마지막 사람이 나가고 상태가 PASSED라면 GP_EXIT로 바꾼 뒤 rcu_sync_call로 콜백을 예약합니다. EXIT는 빠른 길을 다시 열기 위한 마무리 대기입니다. 이 함수가 돌아온 것과 그 콜백이 완료된 것은 다릅니다.', '이미 EXIT인 동안 새 enter와 exit가 이어져 다시 마지막 사람이 나갔다면 GP_REPLAY로 표시합니다. 앞서 예약한 기다림 뒤에 추가 종료가 생겼기 때문입니다. 어느 exit든 즉시 문을 연다는 규칙이 아니라, 수와 단계를 함께 보고 다음 일을 고릅니다.'], [('PASSED에서 참여자 두 명 중 한 명만 exit하면 어떻게 될까요?', ['곧바로 IDLE로 바꾸고 빠른 길을 열어요', '한 명이 남고 빠른 길은 계속 닫혀 있어요'], '2에서 1을 빼면 1이므로 마지막 종료가 아닙니다. 남은 참여자가 있으니 상태를 유지합니다. 한 번 exit했다는 이유만으로 빠른 길을 열면 그 참여자의 전환을 깨뜨립니다.'), ('PASSED에서 마지막 참여자가 exit하면 다음 단계는?', ['EXIT로 바꾸고 콜백을 예약해요', '기다림 없이 즉시 IDLE로 바꿔요'], '마지막 종료 뒤의 유예 기간을 거친 처리가 필요하므로 EXIT와 예약으로 이어집니다. exit 호출 자체가 빠른 길 복귀 완료라는 답은 틀립니다.')]), 'os1438': ('안전 점검을 예약한 뒤 다른 공사까지 새로 끝났다면, 예전 점검 범위에 새 공사가 포함됐다고 그냥 믿으면 안 됩니다. 새로 끝난 일까지 포함해 다시 확인해야 합니다.', 'REPLAY가 나중에 발생한 종료를 포함하는 추가 유예 기간을 요청하는 이유를 이해합니다.', '첫 exit 예약 → 새 enter → 새 exit로 REPLAY → 첫 콜백에서 EXIT와 재예약 → 다음 콜백에서 IDLE을 그리세요. 마지막은 추가 참여가 없는 경우입니다.', ['먼저 A가 마지막 exit를 해서 상태가 EXIT, 참여자 수가 0이고 콜백이 예약됐다고 합시다. 아직 콜백은 끝나지 않았습니다. 예약과 완료 사이에는 다른 작업이 들어올 시간이 있습니다.', '그사이에 B가 enter하면 참여자 수가 1이 됩니다. B는 기존 전환을 이용해 일을 마치고 exit할 수 있습니다. 상태가 아직 EXIT인 동안 마지막 수가 다시 0이 되면 REPLAY로 표시합니다.', 'REPLAY는 처음부터 다시 모든 일을 실행하라는 뜻이 아닙니다. 나중에 끝난 B의 작업까지 고려해 유예 기간 뒤의 처리를 한 번 더 예약해야 한다는 표시입니다. 처음 예약한 기다림만으로 뒤늦은 종료까지 포함한다고 단정할 수 없기 때문입니다.', '첫 콜백이 실행될 때 gp_count=0이고 상태가 REPLAY라면 GP_EXIT로 바꾸고 rcu_sync_call을 다시 호출합니다. 아직 IDLE로 바꾸지 않습니다. 같은 콜백 항목을 다시 맡기는 이 동작은 현재 실행 중인 콜백의 정해진 절차 안에서 일어납니다.', '재예약 뒤 필요한 유예 기간을 거쳐 다음 콜백이 실행됩니다. 그때도 참여자 수가 0이고 새 REPLAY가 없다면 IDLE로 돌아가 빠른 읽기 길을 허용합니다. 중간에 또 변화가 생기면 결과도 그 변화에 따라 달라집니다.', '따라서 무조건 몇 초 더 쉬는 타이머로 외우면 안 됩니다. 중요한 것은 어느 exit 이후의 작업을 기다림에 포함하느냐입니다. 처음 초기화한 IDLE·0에는 이런 뒤늦은 종료가 없으므로, count가 0이라는 이유만으로 REPLAY라고 부르지 않습니다.'], [('참여자 수 0, 상태 REPLAY에서 콜백이 실행되면?', ['무조건 바로 IDLE로 가요', 'EXIT로 바꾸고 콜백을 다시 예약해요'], '뒤늦은 종료를 포함할 추가 유예 기간이 필요합니다. 첫 콜백을 끝냈다는 이유만으로 빠른 길을 열지 않고 재예약하므로 첫 답은 틀립니다.'), ('이 예시에서 REPLAY가 생긴 이유는?', ['종료 콜백을 예약한 뒤 새 enter와 exit가 모두 일어났어요', '새 객체를 초기화했더니 참여자 수가 0이었어요'], '앞선 예약 이후 새로운 완료 시점이 생긴 것이 핵심입니다. 초기화의 0은 아무도 참여하지 않은 시작 상태이며 뒤늦은 종료를 뜻하지 않습니다.')]), 'os1439': ('공사팀이 모두 나갔고 추가 공사도 없으며 마무리 확인까지 끝났습니다. 이제 지름길을 열 수 있습니다. 문을 여는 일은 도서관 건물을 없애는 일과 다릅니다.', '최종 IDLE의 뜻과 객체 해제를 구별합니다.', '콜백에서 count 확인 → 남으면 PASSED / 없으면 REPLAY 확인 → REPLAY면 재예약 / 아니면 IDLE을 그리세요. IDLE 옆에 “빠른 길 허용”을 쓰세요.', ['rcu_sync_func의 분기는 순서대로 읽어야 합니다. 먼저 gp_count를 확인합니다. 정상적인 사용에서 참여자가 남아 있으면 PASSED로 가므로 그 아래 IDLE 복귀 분기까지 내려가지 않습니다.', '참여자가 0이면 REPLAY인지 봅니다. REPLAY는 앞선 콜백 예약 뒤 새 종료가 생겼다는 표시라 추가 기다림을 예약합니다. 수가 0이라는 조건 하나만으로 빠른 길을 열지 않는 이유입니다.', '참여자도 없고 REPLAY도 아닌 정상 종료 경로에서는 WRITE_ONCE로 GP_IDLE을 기록합니다. 이 시점은 필요한 마지막 exit 이후의 유예 기간을 지난 콜백 처리입니다. updater가 자기 exit를 호출한 순간과 구별하세요.', 'IDLE은 reader가 다시 빠른 읽기 길을 이용해도 된다는 상태입니다. reader는 필요한 RCU 보호 문맥에서 rcu_sync_is_idle로 이 상태를 확인하고 상위 알고리즘의 읽기 절차를 따릅니다. 상태 조회만으로 모든 자료의 사용권을 얻지는 않습니다.', '이 코드는 gp_count를 무조건 0으로 덮지 않습니다. 참여자가 없는지를 먼저 확인한 뒤 gp_state를 바꾸는 것입니다. 이미 남아 있는 참여자를 없던 것으로 만들어 빠른 길을 여는 방식이 아닙니다.', 'IDLE 기록은 free 호출도 아닙니다. 자료가 놓인 메모리는 계속 존재할 수 있고 reader도 사용할 수 있습니다. 객체를 없애려면 더 이상의 사용을 막고 사용 중인 작업과 예약을 정리하는 상위 수명 규칙을 따로 지켜야 합니다.'], [('최종 IDLE 상태가 직접 뜻하는 것은?', ['관련 객체의 메모리를 전부 해제했다는 뜻이에요', 'reader가 빠른 읽기 길을 다시 써도 된다는 뜻이에요'], 'IDLE은 경로 허용 상태입니다. 이 분기는 상태를 기록할 뿐 메모리를 반납하는 free를 하지 않습니다. 빠른 길 복귀와 객체 삭제를 섞으면 안 됩니다.'), ('콜백이 실행될 때 참여자가 남아 있으면 IDLE 분기로 갈까요?', ['아니요. 앞의 count 검사에서 PASSED로 가요', '네. 모든 count를 강제로 0으로 덮어요'], 'gp_count를 먼저 검사해 남은 참여자가 있으면 PASSED를 기록합니다. 사람 수를 없애 버리는 코드가 아니며, 따라서 항상 IDLE이라는 해석은 틀립니다.')]), 'os1440': ('도서관 안내판을 치우기 전에는 이용을 끝내고, 그 안내판을 보고 나중에 일할 사람의 예약도 끝내야 합니다. 안내판만 먼저 버리면 남은 사람이 잘못된 곳을 찾아갑니다.', 'RCU-sync 종료 정리가 예약된 콜백의 완료를 기다리는 이유를 배웁니다.', '새 사용 차단 → 모든 enter/exit 사용 종료 → dtor → 필요하면 남은 콜백 완료 대기 → 상위 수명 조건 확인 뒤 해제를 적으세요.', ['rcu_sync_dtor는 rcu_sync 구조체를 더 이상 쓰지 않을 때 마무리하는 함수입니다. dtor는 destructor, 즉 종료 정리를 뜻하는 이름입니다. 이 함수 자체에 구조체를 free하는 코드는 없습니다.', '호출자는 먼저 새 사용을 막고 활성 updater의 enter/exit를 끝내야 합니다. dtor는 PASSED 상태나 남은 gp_count를 경고로 검사합니다. 경고한다고 아직 일하는 updater를 강제로 취소하거나 올바른 종료 순서를 대신 만들어 주지는 않습니다.', '내부 잠금 안에서 REPLAY라면 EXIT로 바꿉니다. 정상 사용에서는 REPLAY 콜백이 한 번 더 예약해야 하지만, 이제 객체 사용을 끝내는 중이고 빠른 길을 다시 이용할 필요도 없습니다. 따라서 남은 콜백이 불필요하게 재예약하지 않고 마무리하도록 합니다.', '현재 상태를 지역 변수에 기억한 뒤 내부 잠금을 풉니다. 기억한 상태가 IDLE이 아니면 rcu_barrier를 호출합니다. 긴 기다림을 내부 spinlock을 잡은 채 하는 것이 아니라 잠금을 푼 다음에 합니다.', 'rcu_barrier는 이미 진행 중인 call_rcu 계열 콜백이 완료되기를 기다리는 약속입니다. synchronize_rcu처럼 유예 기간을 기다리는 약속과 구별하세요. 원문은 시스템에 대기 중인 콜백이 없다면 새 유예 기간을 기다리지 않고 바로 돌아올 수도 있다고 설명합니다.', 'barrier 뒤에는 상태가 IDLE인지 경고 검사로 확인합니다. 여기서 객체 사용 종료의 전제와 남은 콜백 정리가 함께 필요합니다. barrier라는 이름만 보고 새로 들어오는 모든 사용자를 영구 차단한다고 생각하면 안 됩니다. 그 차단은 호출자가 마련해야 합니다.'], [('종료 정리에서 REPLAY를 EXIT로 바꾸는 이유는?', ['새 updater를 한 명 더 추가하려고요', '남은 콜백이 불필요하게 다시 예약되지 않게 하려고요'], '사용을 끝내는 중이므로 남은 콜백을 마무리하도록 합니다. 이 대입은 상태를 바꾸는 것이며 gp_count를 늘려 새 참여자를 만드는 코드가 아닙니다.'), ('rcu_barrier는 콜백이 없어도 반드시 새 유예 기간을 기다릴까요?', ['아니요. 핵심은 이미 진행 중인 콜백의 완료예요', '네. 항상 새로운 유예 기간 하나가 필수예요'], '원문은 대기 중인 콜백이 없다면 바로 반환할 수도 있다고 설명합니다. 콜백 완료 대기와 무조건 새 유예 기간 기다리기를 같은 약속으로 외우면 틀립니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_355.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
